import hashlib,json
from pathlib import Path

RAW=Path('runs/plasticity_diagnosis/S2j/20261006T-fixed-vector-synthetic-v3/fixed_vector_assay.json')
OUT=RAW.parent/'fixed_vector_assay_review.json'; REPORT=RAW.parent/'report.md'
def digest(p): return hashlib.sha256(p.read_bytes()).hexdigest()
d=json.loads(RAW.read_text()); scales=d['scales']; rec=d['records']; expected=56
per={str(s):{'runs':sum(r['scale']==s for r in rec),'complete':sum(r['scale']==s for r in rec)==expected} for s in scales}
onehot={str(s):[next(r['kc_count'] for r in rec if r['scale']==s and r['name']==f'onehot_{i}') for i in range(8)] for s in scales}
review={'status':'S2j_closed','raw_result':{'path':str(RAW),'sha256':digest(RAW),'runs':len(rec),'stimuli_per_scale':expected,'scales':scales,'scale_completeness':per,'equivalence_note':'Raw assay is deterministic/observation-only; no decoder or performance gate.'},'provenance_bug':{'description':'Original v3 JSON had top-level actual scales [1,2,3,4,6,9,12,18] but preregistered.scales inherited the v2 list [3,6,9,12,18,24,30]. Runner is fixed to emit actual distributed scales; raw JSON is preserved and not overwritten.','externally_preregistered_actual_scales':[1,2,3,4,6,9,12,18],'matches_top_level':scales==[1.0,2.0,3.0,4.0,6.0,9.0,12.0,18.0],'raw_preregistered_scales':d.get('preregistered',{}).get('scales')},'distributed_mapping_summary':{'nodes_n':d['adapter_mapping'].get('nodes_n'),'bin_sizes':d['adapter_mapping'].get('bin_sizes'),'channel_masks':d['adapter_mapping'].get('channel_masks'),'channel_group_sizes':d['adapter_mapping'].get('channel_group_sizes'),'theoretical_bin_overlap':d['adapter_mapping'].get('theoretical_bin_overlap'),'mapping_hash':d['adapter_mapping'].get('mapping_hash')},'onehot_kc_counts':onehot,'scale18_onehot_fraction':{'counts':onehot['18.0'],'kc_total':d.get('kc_total',4064),'last_fraction':1414/4064,'limit':0.20},'selection_recomputed':{'status':'no_acceptable_distributed_mapping','raw_selection':d.get('selection'),'selection_unchanged':d.get('selection',{}).get('status')=='no_acceptable_mapping_scale','failure_evidence':['All scales fail onehot 1%-20%/8-way distinct criterion because most onehot KC counts are zero.','At scale18 onehot counts are [0,0,0,0,0,0,0,1414]; 1414/4064=34.8%, above the 20% upper bound.','Therefore zero parity and/or complete onehot acceptance cannot be satisfied; no scale is selected.']},'prior_versions':{'v1':{'path':'runs/plasticity_diagnosis/S2j/20261006T-fixed-vector-synthetic-v1/fixed_vector_assay.json','status':'no_acceptable_mapping_scale','mapping':'3335 R1-R6 only'},'v2':{'path':'runs/plasticity_diagnosis/S2j/20261006T-fixed-vector-synthetic-v2/fixed_vector_assay.json','status':'no_acceptable_mapping_scale','mapping':'3335 R1-R6 + 811 R8'},'v3':{'path':str(RAW),'status':'no_acceptable_distributed_mapping','mapping':'4146 nodes, 16 coordinate bins, fixed Hadamard rows'}},'limitations':['Synthetic mechanism assay only; no market/labels/reward/profit/decoder and no causal claim.','S2j is closed after the frozen v3 distributed attempt; no further mapping or threshold iteration is authorized.']}
OUT.write_text(json.dumps(review,indent=2,allow_nan=False))
REPORT.write_text('# S2j v3 review\n\nStatus: **S2j_closed** / `no_acceptable_distributed_mapping`.\n\nThe preserved raw v3 result contains 448 runs: 8 distributed scales × 56 vectors, with complete per-scale coverage. The runner provenance bug was that `preregistered.scales` inherited the v2 list; the actual externally frozen v3 list is `[1,2,3,4,6,9,12,18]`. The runner is corrected without overwriting the raw JSON.\n\nAt scale 18, one-hot KC counts are `[0,0,0,0,0,0,0,1414]`; `1414/4064 = 34.8%`, exceeding the 20% criterion. The other scales have no complete one-hot response. No distributed mapping scale passes the frozen acceptance rule, so S2j is closed.\n\nThe v1/v2/v3 summaries are descriptive synthetic mechanism results only. They do not involve market data, labels, rewards, decoder decisions, trades, or causal claims.\n')
print(json.dumps({'review':str(OUT),'report':str(REPORT),'raw_sha256':digest(RAW)}))
